css:
.switch__input {
  color: #1c1717;
  font: 1em/1.5 sans-serif;
  transition:
    background-color 0.4s,
    color 0.4s;
}

.switch,
.switch__input {
  -webkit-tap-highlight-color: transparent;
}
.switch {
  display: flex;
  align-items: center;
  margin: auto;
}
.switch__input {
  background: #a72828;
  border-radius: 50px;
  box-shadow:
    inset 0 1px 1px 1px rgba(0, 0, 0, 0.5),
    0 1px 0 0 rgba(255, 255, 255, 0.1);
  outline: none;
  position: relative;
  width: 70px;
  height: 40px;
  transition:
    background-color 0.4s cubic-bezier(0.65, 0, 0.35, 1),
    box-shadow 0.2s ease,
    transform 0.4s cubic-bezier(0.68, -0.6, 0.32, 1.6);
  -webkit-appearance: none;
  appearance: none;
}

.switch__input:before {
  background-color: #e8e3e3;
  border-radius: 50%;
  content: "";
  display: block;
  position: absolute;
  top: 8px;
  left: 8px;
  transition:
    background-color 0.4s,
    transform 0.4s cubic-bezier(0.68, -0.6, 0.32, 1.6);
  width: 25px;
  height: 25px;
}
.switch__letters,
.switch__letter {
  transition: transform 0.4s cubic-bezier(0.68, -0.6, 0.32, 1.6);
}
.switch__letters {
  margin-left: 8px;
  overflow: visible;
  pointer-events: none;
  width: 1.5em;
  height: 1.5em;
  font-size: 34px;
}
.switch__letter:last-child {
  transform: translateX(14px);
}
.switch__letter-stroke {
  stroke: #a72828;
  transition:
    stroke 0.4s cubic-bezier(0.65, 0, 0.35, 1),
    stroke-dashoffset 0.4s cubic-bezier(0.68, -0.6, 0.32, 1.6),
    transform 0.4s cubic-bezier(0.68, -0.6, 0.32, 1.6);
}
.switch__letter-stroke:nth-child(2) {
  transform-origin: 2px 2px;
}
.switch__text {
  overflow: hidden;
  position: absolute;
  width: 1px;
  height: 1px;
}
/* “on” state */
.switch__input:checked {
  background-color: #1fad3e;
}
.switch__input:checked,
.switch__input:checked + .switch__letters {
  transform: translateX(0.375em);
}
.switch__input:checked:before {
  transform: translateX(30px);
}
.switch__input:checked ~ .switch__letters .switch__letter-stroke {
  stroke: #1fad3e;
}
.switch__input:checked ~ .switch__letters .switch__letter-stroke:nth-child(2) {
  stroke-dashoffset: 6;
}
.switch__input:checked ~ .switch__letters .switch__letter-stroke:last-child {
  stroke-dashoffset: 4;
}
.switch__input:checked
  ~ .switch__letters
  .switch__letter:first-child
  .switch__letter-stroke:nth-child(2) {
  stroke-dashoffset: 0;
  transform: rotate(56.5deg);
}
.switch__input:checked ~ .switch__letters .switch__letter:last-child {
  stroke-dashoffset: 0;
  transform: translateX(8px);
}
